# encoding: UTF-8
# 3D-модель торговельної зали магазину взуття ТОВ «Взуття» 20 × 14 м (курсова робота, п. 2.3).
# Запуск у SketchUp: Вікно → Консоль Ruby →  load "шлях/до/vzuttia_zal.rb"
# або Розширення → (Extension Manager не потрібен) — просто load у консолі.
# Згенеровано build_model.py. Після побудови скрипт зберігає поруч vzuttia_zal.skp,
# створює аркуш А1 vzuttia_zal_A1.layout у LayOut і експортує його у vzuttia_zal_A1.pdf.

